// Serializes the vendored Lavish SDK into lib/lavish-sdk.generated.ts.
//
// The SDK runs inside the review iframe, so it ships as source text built with
// Function.prototype.toString(). That must happen here, under plain Node: BB
// compiles server.ts with minify and keepNames, which rewrites function bodies to
// call a module-level `__name` helper the iframe does not have.
//
// Run after syncing vendor/lavish. `--check` fails when the generated file is stale.

import { readFile, writeFile } from "node:fs/promises";

import * as artifactSdk from "../vendor/lavish/artifact-sdk.js";
import * as mermaidNode from "../vendor/lavish/mermaid-node.js";
import * as tableCell from "../vendor/lavish/table-cell.js";

const output = new URL("../lib/lavish-sdk.generated.ts", import.meta.url);

const declare = (name, fn) => `const ${name}=${fn.toString()};`;
const declareAll = (module) => Object.entries(module).map(([name, fn]) => declare(name, fn)).join("\n");

// Expects `key`, `artifactRevision`, `artifactLoadToken`, and `sdkOptions` in scope.
const body = `const deriveQueueKey=${artifactSdk.deriveLavishQueueKey.toString()};
${declare("isNativeInteractiveControl", artifactSdk.isNativeInteractiveControl)}
const MODE_TOGGLE_HOTKEY_KEY=${JSON.stringify(artifactSdk.MODE_TOGGLE_HOTKEY_KEY)};
${[
  "isModeToggleHotkeyEvent",
  "classifySevereTextOverflow",
  "classifyMaterialRectEscape",
  "isMaterialPageOverflow",
  "findStableLayoutFindings",
  "isNearTotalOcclusion",
  "attachmentSizeError",
  "classifyAttachmentBatch",
  "partitionDroppedFiles",
  "planClipboardPaste",
  "acceptedImageTypes",
  "isTrustedAttachmentResult",
  "deriveAttachmentNoticeState",
].map((name) => declare(name, artifactSdk[name])).join("\n")}
${declareAll(mermaidNode)}
const mermaidHelpers={ ${Object.keys(mermaidNode).join(", ")} };
${declareAll(tableCell)}
(${artifactSdk.createArtifactSdk.toString()})(deriveQueueKey, isNativeInteractiveControl, mermaidHelpers, artifactRevision, artifactLoadToken, key, sdkOptions);`;

const contents = `// Generated by scripts/generate-lavish-sdk.mjs from vendor/lavish. Do not edit.
export const LAVISH_SDK_SOURCE = ${JSON.stringify(body)};
`;

if (process.argv.includes("--check")) {
  const current = await readFile(output, "utf8").catch(() => "");
  if (current !== contents) {
    console.error("lib/lavish-sdk.generated.ts is stale. Run: node scripts/generate-lavish-sdk.mjs");
    process.exit(1);
  }
} else {
  await writeFile(output, contents);
}
